/* 공개 사이트용 데이터 모듈 — 일정은 암호화되어 있고, 비밀번호로 이 기기에서만 풀어요.
 * tools/build.ps1 이 js/data.js 를 AES-GCM(PBKDF2-SHA256) 으로 암호화해 이 파일을 만들어요. */
const P = {"v":1,"iter":310000,"salt":"ykVgW0V5lXGu8eezjq+qhg==","iv":"s1sL2wqaOzHq8OS7","ct":""};
const KEY_STORE = 'hkbkk:key';
const b64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const toB64 = (u8) => btoa(String.fromCharCode(...u8));

async function keyFromPassword(pw) {
  const base = await crypto.subtle.importKey('raw', new TextEncoder().encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: b64(P.salt), iterations: P.iter }, base, 256);
  return new Uint8Array(bits);
}
async function openWith(raw) {
  const key = await crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['decrypt']);
  const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: b64(P.iv) }, key, b64(P.ct));
  return JSON.parse(new TextDecoder().decode(plain));
}
const storeGet = () => { try { return localStorage.getItem(KEY_STORE); } catch { return null; } };
const storeSet = (v) => { try { localStorage.setItem(KEY_STORE, v); } catch { /* 저장 불가 환경 */ } };

window.TRIP_LOCK = { forget() { try { localStorage.removeItem(KEY_STORE); } catch { /* 무시 */ } } };

async function unlock() {
  const saved = storeGet();
  if (saved) {
    try { return await openWith(b64(saved)); } catch { window.TRIP_LOCK.forget(); }
  }
  return new Promise((resolve) => {
    const css = document.createElement('style');
    css.textContent = `
      .lock { position: fixed; inset: 0; z-index: 200; display: grid; place-items: end center; color: #fff; background: #0f1420; overflow: hidden; }
      .lock img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .0; transform: scale(1.08); transition: opacity 1.2s, transform 6s cubic-bezier(.22,1,.36,1); }
      .lock img.on { opacity: .75; transform: scale(1); }
      .lock::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(8,10,20,.35), rgba(8,10,20,.2) 40%, rgba(8,10,20,.92)); }
      .lock form { position: relative; z-index: 1; width: min(420px, calc(100% - 32px)); margin-bottom: calc(40px + env(safe-area-inset-bottom, 0px)); animation: lockIn .9s cubic-bezier(.22,1,.36,1) both; }
      .lock .eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .16em; opacity: .8; }
      .lock h1 { margin: 10px 0 6px; font-size: clamp(34px, 10vw, 48px); font-weight: 800; letter-spacing: -.04em; line-height: 1.08; }
      .lock p { margin: 0 0 22px; opacity: .85; font-size: 15px; }
      .lock .row { display: flex; gap: 8px; padding: 6px; border-radius: 20px; background: rgba(255,255,255,.14); -webkit-backdrop-filter: blur(18px); backdrop-filter: blur(18px); box-shadow: inset 0 0 0 1px rgba(255,255,255,.28); }
      .lock input { flex: 1; min-width: 0; height: 50px; padding: 0 14px; border: 0; border-radius: 14px; background: transparent; color: #fff; font: 700 20px/1 inherit; letter-spacing: .3em; outline: none; }
      .lock input::placeholder { color: rgba(255,255,255,.55); letter-spacing: 0; font-weight: 500; font-size: 15px; }
      .lock button { height: 50px; padding: 0 20px; border: 0; border-radius: 14px; background: #fff; color: #1c1a18; font: 800 15px/1 inherit; cursor: pointer; }
      .lock button:disabled { opacity: .6; }
      .lock .msg { min-height: 20px; margin-top: 10px; font-size: 13.5px; color: #ffb4a8; }
      .lock.shake form { animation: shake .42s; }
      .lock.out { opacity: 0; transition: opacity .6s; pointer-events: none; }
      @keyframes lockIn { from { opacity: 0; transform: translateY(24px); } }
      @keyframes shake { 20%, 60% { transform: translateX(-10px); } 40%, 80% { transform: translateX(10px); } }
      @media (prefers-reduced-motion: reduce) { .lock *, .lock { animation: none !important; transition: none !important; } }`;
    document.head.appendChild(css);
    const el = document.createElement('div');
    el.className = 'lock';
    el.innerHTML = `
      <img alt="" referrerpolicy="no-referrer" src="https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Panorama_of_Hong_Kong_Harbour_from_The_Peak_dllu.jpg/1920px-Panorama_of_Hong_Kong_Harbour_from_The_Peak_dllu.jpg">
      <form autocomplete="off">
        <div class="eyebrow">HONG KONG · BANGKOK · 2026</div>
        <h1>여행을 이어볼까요?</h1>
        <p>가족 전용 여행 안내예요. 비밀번호를 입력해 우리 일정을 열어보세요.</p>
        <div class="row">
          <input type="password" inputmode="numeric" autocomplete="current-password" placeholder="비밀번호" aria-label="비밀번호" required>
          <button type="submit">열기</button>
        </div>
        <div class="msg" role="alert"></div>
      </form>`;
    document.body.appendChild(el);
    const img = el.querySelector('img');
    img.addEventListener('load', () => img.classList.add('on'));
    const form = el.querySelector('form');
    const input = el.querySelector('input');
    const btn = el.querySelector('button');
    const msg = el.querySelector('.msg');
    setTimeout(() => input.focus(), 300);
    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      btn.disabled = true;
      msg.textContent = '';
      try {
        const raw = await keyFromPassword(input.value.trim());
        const data = await openWith(raw);
        storeSet(toB64(raw));
        try { if (navigator.userActivation?.hasBeenActive) navigator.vibrate?.([12, 60, 22]); } catch { /* 무시 */ }
        el.classList.add('out');
        setTimeout(() => { el.remove(); css.remove(); }, 650);
        resolve(data);
      } catch {
        try { if (navigator.userActivation?.hasBeenActive) navigator.vibrate?.([40, 50, 40]); } catch { /* 무시 */ }
        msg.textContent = '비밀번호가 맞지 않아요. 다시 입력해 주세요.';
        el.classList.remove('shake'); void el.offsetWidth; el.classList.add('shake');
        input.select();
        btn.disabled = false;
      }
    });
  });
}

const data = await unlock();
export const { PHOTOS, TRIP, KIND, CITY, DAYS, BRANCH } = data;
